mapper.select:
select i.id, i.ticket_id, i.visit_date, i.timeslot_id, t.name as timeslot_name, i.total_qty, i.sold_qty, i.locked_qty, i.status
from ticket_inventory i join timeslot t on i.timeslot_id=t.id
where i.ticket_id=#{ticketId} and i.visit_date=#{visitDate}

mapper.update:
update ticket_inventory set locked_qty=locked_qty + #{qty}, updated_at=now()
where ticket_id=#{ticketId} and visit_date=#{visitDate} and timeslot_id=#{timeslotId}
  and status=1 and (total_qty - sold_qty - locked_qty) >= #{qty}
